import { isName, toPrimaryName, primaryKeyToFingerprintedName } from "./Name.js";
import { isPrimaryKey, primaryKeyToFingerprint } from "./PrimaryKey.js";
import { getLastSecondaryCharIndex } from "./lib/characters.js";
import isString from "./lib/utils/isString.js";
const delimiter = "@";
export const parseNameKey = (nameKey) => {
    let name = undefined;
    let rest = undefined;
    const containsDelimiter = nameKey.includes(delimiter);
    if (containsDelimiter) {
        [name, rest] = nameKey.split(delimiter);
    }
    else {
        const index = getLastSecondaryCharIndex(nameKey);
        if (index > -1) {
            [name, rest] = [nameKey.slice(0, index + 1), nameKey.slice(index + 1)];
        }
    }
    if (name === undefined || rest === undefined) {
        throw new Error(`Invalid NameKey: ${nameKey}`);
    }
    if (isName(name) === false) {
        throw new Error(`Invalid Name in NameKey: ${nameKey}`);
    }
    const primaryName = toPrimaryName(name);
    const primaryKey = `${primaryName}${rest}`;
    if (isPrimaryKey(primaryKey) === false) {
        throw new Error(`${primaryKey}: Invalid PrimaryKey in NameKey: ${nameKey}`);
    }
    return [primaryKey, name, toNameKey(name, primaryKey)];
};
export const toNameKey = (name, primaryKey) => {
    if (toPrimaryName(name) !== primaryKey.slice(0, name.length)) {
        throw new Error(`Name: ${name} does not belong to PrimaryKey: ${primaryKey}`);
    }
    return `${name}${delimiter}${primaryKey.slice(name.length)}`;
};
export const isNameKey = (value) => {
    if (isString(value) === false)
        return false;
    try {
        parseNameKey(value);
        return true;
    }
    catch {
        return false;
    }
};
export const nameKeyToPrimaryKey = (nameKey) => {
    const [primaryKey] = parseNameKey(nameKey);
    return primaryKey;
};
export const nameKeyToFingerprint = async (nameKey) => {
    const [primaryKey] = parseNameKey(nameKey);
    return await primaryKeyToFingerprint(primaryKey);
};
export const nameKeyToFingerprintedName = async (nameKey) => {
    const [primaryKey, name] = parseNameKey(nameKey);
    const [fingerprintedName] = await primaryKeyToFingerprintedName(primaryKey, name);
    return fingerprintedName;
};
